import {delay,checksum,subnet,fragments,shortest} from './core.js';
import {W} from './worked.js';
export const mathFamilies=[
{id:'delay',ch:0,name:'Độ trễ store-and-forward',pages:[12,17],qid:'l3q0'},
{id:'throughput',ch:0,name:'Thông lượng và thời gian truyền file',pages:[17,27],qid:'extra-q13'},
{id:'http',ch:1,name:'HTTP tuần tự và RTT',pages:[27,29],qid:'extra-q31'},
{id:'checksum',ch:2,name:'Checksum bù 1',pages:[19,22],qid:'extra-q34'},
{id:'tcpAck',ch:2,name:'TCP ACK và lỗ hổng byte',pages:[51,52],qid:'l19q0'},
{id:'tcpWindow',ch:2,name:'TCP rwnd/cwnd và dữ liệu đang bay',pages:[56,58],qid:'extra-q45'},
{id:'subnet',ch:3,name:'IPv4 network, broadcast và host',pages:[18,37],qid:'extra-q52'},
{id:'fragment',ch:3,name:'Phân mảnh IPv4',pages:[47,48],qid:'v3-4-3'},
{id:'routing',ch:3,name:'Đường đi tối ưu và chi phí',pages:[65,79],qid:'extra-q62'}];
export function randomSeed(seed){let a=seed>>>0;return ()=>{a+=0x6D2B79F5;let t=a;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return ((t^t>>>14)>>>0)/4294967296}}
const int=(x,min,max,name)=>{if(!Number.isInteger(x)||x<min||x>max)throw Error(name+' ngoài giới hạn hợp lệ.');return x};
export function calculate(f,p){switch(f){
case 'delay':int(p.bytes,64,8000,'byte');int(p.rate,1,100,'Mbps');int(p.links,1,5,'link');int(p.km,1,3000,'km');return delay(p.bytes,p.rate,p.km,2e8,p.links,1).one*1000;
case 'throughput':int(p.fileMb,1,100,'Mb');if(!Array.isArray(p.rates)||p.rates.length!==3)throw Error('Cần 3 link.');p.rates.forEach(x=>int(x,1,100,'Mbps'));return p.fileMb/Math.min(...p.rates);
case 'http':int(p.images,1,8,'ảnh');int(p.rtt,10,100,'RTT');int(p.tx,1,20,'thời gian phát');return (p.images+1)*(2*p.rtt+p.tx);
case 'checksum':int(p.a,0,65535,'word');int(p.b,0,65535,'word');return checksum([p.a,p.b]);
case 'tcpAck':int(p.start,1,10000,'Seq');int(p.len,10,1500,'payload');if(typeof p.gap!=='boolean')throw Error('Thiếu giả thiết lỗ hổng.');return p.start+p.len*(p.gap?1:3);
case 'tcpWindow':int(p.buffer,1000,64000,'buffer');int(p.used,0,p.buffer,'used');int(p.cwnd,500,64000,'cwnd');int(p.flight,0,64000,'flight');return Math.max(0,Math.min(p.buffer-p.used,p.cwnd)-p.flight);
case 'subnet':int(p.last,0,255,'octet');int(p.prefix,25,29,'prefix');return Number(subnet('192.168.7.'+p.last,p.prefix).broadcast.split('.').at(-1));
case 'fragment':int(p.total,600,12000,'total');int(p.mtu,500,1500,'MTU');return fragments(p.total,p.mtu,20).length;
case 'routing':if(!Array.isArray(p.edges)||p.edges.length!==5||p.edges.some(e=>e.length!==3||!['a','b','c','d'].includes(e[0])||!['a','b','c','d'].includes(e[1])||!Number.isInteger(e[2])||e[2]<1||e[2]>20))throw Error('Đồ thị không hợp lệ.');return shortest(p.edges,'a').dist.d;
default:throw Error('Dạng bài chưa hỗ trợ.')}}
const fmt=n=>Number(n.toFixed(6)).toString();
export function generateProblem(family,seed=1){let meta=mathFamilies.find(f=>f.id===family);if(!meta)throw Error('Dạng bài không tồn tại.');let r=randomSeed(seed),pick=(a,b)=>a+Math.floor(r()*(b-a+1)),p,prompt,symbols,convert,formula,sub,unit,rows,assumptions,candidates=[];
switch(family){
case 'delay':p={bytes:pick(4,20)*100,rate:pick(1,10),links:pick(2,4),km:pick(1,20)*50};prompt=`Một gói ${p.bytes} byte qua ${p.links} link cùng ${p.rate} Mbps, mỗi link dài ${p.km} km; s=2×10⁸ m/s. Tổng trễ là bao nhiêu ms?`;symbols='L: bit/gói; R: bit/s; d: mét; s: m/s; N: số link.';convert=`L=${p.bytes*8} bit; R=${p.rate*1e6} bit/s; d=${p.km*1000} m.`;formula='T=N(L/R+d/s)';sub=`${p.links}×(${p.bytes*8}/${p.rate*1e6}+${p.km*1000}/200000000)×1000 ms`;unit='ms';assumptions='Store-and-forward, không có xử lý/hàng đợi, các link giống nhau, một gói.';rows=[['L',p.bytes,'byte'],['R',p.rate,'Mbps'],['d',p.km,'km'],['s',2e8,'m/s'],['N',p.links,'link']];candidates=[[p.links*p.bytes/(p.rate*1e6)*1000+p.links*p.km/200,'Quên đổi byte sang bit.'],[p.links*p.bytes*8/(p.rate*1e6)*1000,'Bỏ toàn bộ trễ lan truyền.'],[p.bytes*8/(p.rate*1e6)*1000+p.km/200,'Chỉ tính một link thay vì cả tuyến.']];break;
case 'throughput':p={fileMb:pick(2,20),rates:[pick(1,5),pick(6,10),pick(11,20)]};prompt=`Tệp ${p.fileMb} megabit qua 3 link ${p.rates.join(', ')} Mbps, không cạnh tranh. Tính thời gian xấp xỉ truyền tệp theo giây.`;symbols='F: bit tệp; B: thông lượng nút thắt; t: thời gian.';convert=`F=${p.fileMb}×10⁶ bit; các tốc độ nhân 10⁶ bit/s.`;formula='B=min(R₁,R₂,R₃); t=F/B';sub=`B=${Math.min(...p.rates)} Mbps; t=${p.fileMb}/${Math.min(...p.rates)}`;unit='s';assumptions='Mb là megabit thập phân, bỏ khởi động và trễ đường đi; không dùng MB.';rows=[['F',p.fileMb,'Mb'],...p.rates.map((v,i)=>['R'+(i+1),v,'Mbps'])];candidates=[[p.fileMb/Math.max(...p.rates),'Dùng link nhanh nhất thay nút thắt.'],[p.fileMb/p.rates.reduce((a,b)=>a+b,0),'Cộng các tốc độ nối tiếp.'],[p.fileMb*8/Math.min(...p.rates),'Nhầm megabit thành megabyte.']];break;
case 'http':p={images:pick(1,5),rtt:pick(2,8)*10,tx:pick(1,10)};prompt=`HTML và ${p.images} ảnh tải tuần tự, non-persistent HTTP, mỗi đối tượng phát mất ${p.tx} ms, RTT=${p.rtt} ms. Bỏ DNS. Tổng thời gian bao nhiêu ms?`;symbols='O: đối tượng; RTT: đi-về; t_tx: thời gian phát/đối tượng.';convert='Các thời gian đều theo ms; O=1+số ảnh.';formula='T=O(2RTT+t_tx)';sub=`(${p.images}+1)×(2×${p.rtt}+${p.tx})`;unit='ms';assumptions='Một TCP/đối tượng, tải nối tiếp, không cache, không song song, cùng thời gian phát cho từng đối tượng.';rows=[['HTML',1,'đối tượng'],['Ảnh',p.images,'đối tượng'],['RTT',p.rtt,'ms'],['t_tx',p.tx,'ms']];candidates=[[p.images*(2*p.rtt+p.tx),'Bỏ đối tượng HTML gốc.'],[(p.images+1)*(p.rtt+p.tx),'Bỏ một RTT của mỗi kết nối.'],[2*p.rtt+(p.images+1)*p.tx,'Áp dụng tái dùng kết nối dù đề là non-persistent.']];break;
case 'checksum':p={a:pick(1,65000),b:pick(1,65000)};prompt=`Hai từ 16 bit hex ${p.a.toString(16).toUpperCase()} và ${p.b.toString(16).toUpperCase()}. Tính Internet checksum, nhập giá trị thập phân.`;symbols='S: tổng bù 1; C: checksum 16 bit.';convert=`Hai word bằng ${p.a} và ${p.b} thập phân; FFFF hex=65535.`;formula='S=fold16(a+b); C=65535−S';sub=`a+b=${p.a+p.b}; cộng vòng bit nhớ rồi đảo 16 bit`;unit='thập phân';assumptions='Bài rút gọn chỉ trên hai từ cho sẵn, chưa có pseudo-header; dùng bù 1, không phải bù 2.';rows=[['a',p.a,'thập phân'],['b',p.b,'thập phân']];candidates=[[(p.a+p.b)&65535,'Chỉ giữ tổng thấp, chưa cộng vòng và đảo bit.'],[65535-((p.a+p.b)&65535),'Bỏ bit nhớ vượt 16 bit.'],[(calculate(family,p)+1)&65535,'Lấy bù 2 thay bù 1.']];break;
case 'tcpAck':p={start:pick(1,50)*100,len:pick(1,8)*100,gap:r()>.5};prompt=`TCP bắt đầu dữ liệu ở Seq=${p.start}. Ba segment, mỗi segment ${p.len} byte; ${p.gap?'segment thứ hai mất, thứ nhất và thứ ba đã nhận':'cả ba nhận liên tục'}. ACK cộng dồn là bao nhiêu?`;symbols='Seq: số thứ tự byte đầu; L: byte/segment; ACK: byte đầu đang chờ.';convert='Số thứ tự byte; không đếm theo số segment.';formula=p.gap?'ACK=Seq+L':'ACK=Seq+3L';sub=p.gap?`${p.start}+${p.len}`:`${p.start}+3×${p.len}`;unit='số thứ tự byte';assumptions='Kết nối đã thiết lập, Seq là byte dữ liệu đầu, không cộng SYN/FIN; ACK chỉ xác nhận chuỗi liên tục.';rows=[['Seq',p.start,'số byte'],['L',p.len,'byte'],['Số segment',3,'segment'],['Mất segment 2',p.gap?'Có':'Không','']];candidates=[[p.start+3*p.len,'Nhảy qua lỗ hổng như thể đã nhận liên tục.'],[p.start,'Chưa tính byte dữ liệu đã nhận.'],[p.start+p.len*(p.gap?1:3)-1,'Ghi byte cuối nhận được thay byte tiếp theo.']];break;
case 'tcpWindow':p={buffer:pick(4,16)*1000,used:pick(1,3)*1000,cwnd:pick(3,10)*1000,flight:pick(0,2)*1000};prompt=`Buffer=${p.buffer} byte, chưa đọc ${p.used} byte; cwnd=${p.cwnd} byte, đang bay ${p.flight} byte. Có thể gửi thêm tối đa bao nhiêu byte?`;symbols='rwnd: chỗ trống nhận; cwnd: cửa sổ mạng; F: dữ liệu đang bay; A: có thể phát thêm.';convert='Mọi đại lượng đều theo byte.';formula='rwnd=buffer−used; A=max(0,min(rwnd,cwnd)−F)';sub=`rwnd=${p.buffer}-${p.used}; A=max(0,min(${p.buffer-p.used},${p.cwnd})-${p.flight})`;unit='byte';assumptions='Mô hình cửa sổ đơn giản, không tính TCP options/window scaling; dữ liệu đang bay chưa ACK.';rows=[['RcvBuffer',p.buffer,'byte'],['Used',p.used,'byte'],['cwnd',p.cwnd,'byte'],['Flight',p.flight,'byte']];candidates=[[Math.min(p.buffer-p.used,p.cwnd),'Quên trừ phần đang bay.'],[Math.max(0,p.buffer-p.used-p.flight),'Chỉ tôn trọng rwnd, bỏ cwnd.'],[Math.max(0,Math.max(p.buffer-p.used,p.cwnd)-p.flight),'Lấy max hai cửa sổ thay min.']];break;
case 'subnet':p={last:pick(1,254),prefix:pick(25,29)};prompt=`IP 192.168.7.${p.last}/${p.prefix} có broadcast 192.168.7.X. Nhập X.`;symbols='p: prefix; h: bit host; B: địa chỉ/block; N: octet mạng.';convert=`h=32−${p.prefix}; B=2^h=${2**(32-p.prefix)}.`;formula='N=floor(octet/B)×B; broadcast=N+B−1';sub=`N=floor(${p.last}/${2**(32-p.prefix)})×${2**(32-p.prefix)}; X=N+${2**(32-p.prefix)}−1`;unit='octet';assumptions='Subnet thông thường, p từ /25 đến /29; dùng CIDR đã cho, không thay bằng mask mặc định lớp C.';rows=[['IP','192.168.7.'+p.last,'IPv4'],['Prefix',p.prefix,'bit']];let net=Number(subnet('192.168.7.'+p.last,p.prefix).network.split('.').at(-1));candidates=[[net,'Dùng địa chỉ mạng thay broadcast.'],[net+2**(32-p.prefix)-2,'Dùng host cuối thay broadcast.'],[255,'Dùng broadcast /24 bất kể prefix đề cho.']];break;
case 'fragment':p={total:pick(16,90)*100,mtu:[500,620,1000,1500][pick(0,3)]};prompt=`IPv4 datagram ${p.total} byte (gồm header 20 byte), MTU=${p.mtu} byte. DF=0, header mỗi mảnh 20 byte. Có bao nhiêu mảnh?`;symbols='T: tổng datagram; H: header; D: dữ liệu gốc; C: dữ liệu tối đa/mảnh không cuối.';convert=`D=${p.total}−20 byte; dữ liệu mảnh không cuối là bội 8.`;formula='C=floor((MTU−H)/8)×8; n=ceil(D/C) khi T>MTU';sub=`C=floor((${p.mtu}−20)/8)×8=${Math.floor((p.mtu-20)/8)*8}; n=ceil((${p.total}−20)/C)`;unit='mảnh';assumptions='Không IP options, DF=0, ghép tại đích; offset đo theo 8 byte; mảnh cuối không cần payload bội 8.';rows=[['Total',p.total,'byte'],['MTU',p.mtu,'byte'],['Header',20,'byte']];candidates=[[Math.floor((p.total-20)/(p.mtu-20)),'Làm tròn xuống thay làm tròn lên.'],[Math.ceil(p.total/p.mtu),'Chia tổng chiều dài cho MTU, bỏ header mỗi mảnh.'],[calculate(family,p)+1,'Đếm thêm một mảnh rỗng sau mảnh cuối.']];break;
case 'routing':p={edges:[['a','b',pick(1,9)],['a','c',pick(1,9)],['b','c',pick(1,9)],['b','d',pick(1,9)],['c','d',pick(1,9)]]};prompt=`Đồ thị vô hướng: ${p.edges.map(e=>e[0]+'–'+e[1]+'='+e[2]).join(', ')}. Chi phí đường ngắn nhất từ a tới d?`;symbols='c(u,v): chi phí cạnh; D(v): chi phí tạm từ a.';convert='Các trọng số không âm, cùng đơn vị chi phí.';formula='D(v)=min(D(v),D(w)+c(w,v))';sub=shortest(p.edges,'a').steps.map(s=>s.u+': '+Object.entries(s.dist).map(([k,v])=>k+'='+v).join(', ')).join('; ');unit='chi phí';assumptions='Đồ thị vô hướng; có thể có nhiều tuyến đồng chi phí, bài chỉ hỏi chi phí tối ưu.';rows=p.edges.map(e=>[e[0]+'–'+e[1],e[2],'chi phí']);candidates=[[p.edges[0][2]+p.edges[3][2],'Chỉ xét đường a–b–d, chưa so các đường còn lại.'],[p.edges.reduce((s,e)=>s+e[2],0),'Cộng mọi cạnh của mạng thay chi phí một đường.'],[calculate(family,p)+1,'Cộng nhầm thêm một đơn vị chi phí.']];break;
}
let answer=calculate(family,p),options=[fmt(answer)+' '+unit],reasons=['Đúng theo phép tính tham chiếu.'];for(let [v,reason] of [...candidates,[answer+2,'Sai phép cộng/trừ ở bước cuối.'],[answer+3,'Sai phép cộng/trừ ở bước cuối.'],[answer+4,'Sai phép cộng/trừ ở bước cuối.'],[answer-2,'Trừ thiếu ở bước cuối.'],[answer-3,'Trừ thiếu ở bước cuối.'],[answer-4,'Trừ thiếu ở bước cuối.']]){let label=fmt(v)+' '+unit;if(Number.isFinite(v)&&v>=0&&(family!=='subnet'||v<=255)&&!options.includes(label)&&Math.abs(v-answer)>1e-5){options.push(label);reasons.push(reason)}if(options.length===4)break}if(options.length!==4)throw Error('Không tạo được bốn lựa chọn khác nhau.');let worked=W(prompt,symbols,convert,formula,sub,fmt(answer)+' '+unit);return {id:family+':'+(seed>>>0),family,seed:seed>>>0,ch:meta.ch,qid:meta.qid,pages:meta.pages,prompt,answer,unit,options,correct:0,reasons,rows,assumptions,worked,params:p,grading:{integer:!['ms','s'].includes(unit),absTol:['ms','s'].includes(unit)?.00001:0,relTol:0}};
}
export const fixedGeneratedVariants=mathFamilies.flatMap(f=>[11,23,37,53].map(seed=>({family:f.id,seed,ch:f.ch})));
